"use client";

import { useActionState } from "react";
import { useFormStatus } from "react-dom";
import { BadgeCheck, Building2, LoaderCircle, LockKeyhole, Send } from "lucide-react";
import { motion } from "motion/react";
import { submitVendorApplication, type VendorApplicationState } from "@/app/(marketing)/vendors/actions";

const initial: VendorApplicationState = { status: "idle", message: "" };
const input = "h-12 w-full rounded-xl border border-line bg-white px-4 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100";

export function PublicVendorApplicationForm({ organizationId, organizationName }: { organizationId: string; organizationName: string }) {
  const [state, action] = useActionState(submitVendorApplication, initial);
  if (state.status === "success") return <motion.section initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="rounded-3xl border border-blue-100 bg-white p-8 text-center shadow-xl sm:p-12"><BadgeCheck className="mx-auto text-blue-600" size={48} /><h2 className="mt-6 text-3xl font-bold">Application received</h2><p className="mx-auto mt-4 max-w-lg text-sm leading-7 text-muted">{state.message} The procurement team will verify your credentials before portal access is issued.</p>{state.reference && <p className="mx-auto mt-6 w-fit rounded-xl bg-blue-50 px-5 py-3 font-mono text-sm font-bold text-blue-800">Vendor reference: {state.reference}</p>}</motion.section>;
  return <form action={action} className="overflow-hidden rounded-3xl border border-line bg-white shadow-[0_24px_70px_rgba(25,72,133,.10)]"><input type="hidden" name="organizationId" value={organizationId} /><input className="absolute -left-[9999px]" name="websiteCheck" tabIndex={-1} autoComplete="off" /><div className="border-b border-line bg-gradient-to-r from-blue-50 to-white p-6 sm:p-8"><span className="grid size-12 place-items-center rounded-2xl bg-blue-600 text-white"><Building2 size={22} /></span><h2 className="mt-5 text-2xl font-bold">Vendor registration</h2><p className="mt-2 text-sm text-muted">Complete all required information for {organizationName}.</p></div><div className="grid gap-5 p-6 sm:grid-cols-2 sm:p-8"><Field label="Company / trading name *" name="companyName" required /><Field label="Registered legal name *" name="legalName" required /><Field label="Primary contact name *" name="contactName" required /><Field label="Business email *" name="email" type="email" required /><Field label="Phone" name="phone" /><Select label="Vendor category *" name="category" values={["raw_material", "finished_goods", "spare_parts", "logistics_provider", "services"]} /><Field label="Tax ID *" name="taxId" required /><Field label="Registration number *" name="registrationNumber" required /><Field label="Website" name="website" /><Field label="Delivery capacity" name="deliveryCapacity" type="number" min="0" defaultValue="0" /><Field label="Business address *" name="address" required className="sm:col-span-2" /><Field label="City *" name="city" required /><Field label="Delivery methods · comma separated" name="deliveryMethods" placeholder="Own fleet, courier, freight" /><Field label="Service areas · comma separated" name="serviceAreas" placeholder="Metro Manila, Luzon" className="sm:col-span-2" /><label className="sm:col-span-2"><span className="mb-2 block text-sm font-bold">Products and services offered *</span><textarea name="productsServices" required className="min-h-32 w-full rounded-xl border border-line p-4 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100" /></label><div className="sm:col-span-2 rounded-2xl border border-line bg-mist p-4"><h3 className="font-bold">Credential documents</h3><p className="mt-1 text-xs text-muted">PDF, DOCX, JPG, or PNG · maximum 8 MB each</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><FileField label="Tax registration *" name="taxDocument" required /><FileField label="Business registration *" name="registrationDocument" required /><FileField label="Certification (optional)" name="certificationDocument" /></div></div><label className="sm:col-span-2 flex items-start gap-3 rounded-xl border border-blue-100 bg-blue-50 p-4 text-sm leading-6 text-blue-900"><input type="checkbox" name="consent" required className="mt-1 size-4 accent-blue-600" /><span>I certify that the information is accurate and consent to credential verification, secure document storage, and procurement evaluation.</span></label>{state.status === "error" && <p role="alert" className="sm:col-span-2 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{state.message}</p>}</div><div className="flex flex-col gap-4 border-t border-line bg-mist p-6 sm:flex-row sm:items-center sm:justify-between sm:px-8"><p className="flex items-center gap-2 text-xs text-muted"><LockKeyhole size={13} /> Encrypted and access-controlled</p><Submit /></div></form>;
}

function Submit() { const { pending } = useFormStatus(); return <button disabled={pending} className="inline-flex h-12 items-center justify-center gap-2 rounded-xl bg-blue-600 px-6 text-sm font-bold text-white disabled:opacity-60">{pending ? <LoaderCircle className="animate-spin" size={16} /> : <Send size={16} />} Submit application</button>; }
function Field({ label, className, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) { return <label className={className}><span className="mb-2 block text-sm font-bold">{label}</span><input {...props} className={input} /></label>; }
function FileField({ label, name, required }: { label: string; name: string; required?: boolean }) { return <label><span className="mb-2 block text-sm font-bold">{label}</span><input type="file" name={name} required={required} accept=".pdf,.docx,.jpg,.jpeg,.png" className="block w-full rounded-xl border border-line bg-white text-sm file:mr-3 file:border-0 file:bg-blue-50 file:p-3" /></label>; }
function Select({ label, name, values }: { label: string; name: string; values: string[] }) { return <label><span className="mb-2 block text-sm font-bold">{label}</span><select name={name} className={input}>{values.map((value) => <option key={value} value={value}>{value.replaceAll("_", " ").replace(/^./, (letter) => letter.toUpperCase())}</option>)}</select></label>; }
